import Link from "@/components/navigation-link";
import { Brand } from "@/components/brand";
import { Icon } from "@/components/icon";
import type { LandingDictionary } from "@/app/i18n/dictionaries";
import type { Locale } from "@/app/i18n/config";
import { publicSupportEmail } from "@/lib/public-settings";
import { isDatabaseUnavailable } from "@/lib/db-errors";
import { imageCredits } from "@/lib/image-credits";
import { siteContact } from "@/lib/site-contact";

const socialLinks = [
  { label: "WhatsApp", icon: "whatsapp", href: siteContact.whatsappUrl },
  { label: "Telegram", icon: "telegram", href: siteContact.telegramUrl },
  { label: "Instagram", icon: "instagram", href: siteContact.instagramUrl },
] as const;

export async function SiteFooter({
  dictionary,
  locale = "ru",
  offline = false,
}: {
  dictionary: LandingDictionary;
  locale?: Locale;
  offline?: boolean;
}) {
  const { footer, accessibility } = dictionary;
  const supportEmail = (offline ? null : await publicSupportEmail().catch((error: unknown) => {
    if (!isDatabaseUnavailable(error)) throw error;
    console.warn(`[footer] Support email unavailable (${error.code}); using the default contact email. Check DATABASE_URL and database connectivity.`);
    return null;
  })) || siteContact.email;
  return (
    <footer className="site-footer">
      <div className="footer-top section-shell">
        <div className="footer-brand">
          <Brand label={accessibility.brandHome} href={`/${locale}`} />
          <p>{footer.statementLine1}<br />{footer.statementLine2}</p>
          <div className="footer-socials">
            {socialLinks.map(({ label, icon, href }) => href ? (
              <a key={label} className="footer-social" href={href} target="_blank" rel="noopener noreferrer" aria-label={label} title={label}>
                <Icon name={icon} size={30} />
              </a>
            ) : (
              <span key={label} className="footer-social" role="link" aria-disabled="true" aria-label={label} title={label}>
                <Icon name={icon} size={30} />
              </span>
            ))}
          </div>
        </div>
        <nav className="footer-nav" aria-label={footer.navigation}>
          <div>
            <strong>{footer.discover}</strong>
            <Link href={`/${locale}/catalog`}>{footer.cabins}</Link>
            <Link href={`/${locale}#destinations`}>{footer.destinations}</Link>
            <Link href={`/${locale}#how-it-works`}>{footer.howItWorks}</Link>
          </div>
          <div>
            <strong>{footer.about}</strong>
            <Link href={`/${locale}/owner`}>{footer.owners}</Link>
            <Link href={`/${locale}#faq`}>{footer.faq}</Link>
            <Link href={`/${locale}/account`}>{dictionary.header.accountTitle}</Link>
          </div>
          <div className="footer-contact" id="site-contact">
            <strong>{footer.contact}</strong>
            <a href={`mailto:${encodeURIComponent(supportEmail)}`}>
              <Icon name="mail" size={18} /><span>{supportEmail}</span>
            </a>
            <a href={`tel:${siteContact.phone}`}>
              <Icon name="phone" size={18} /><span>{siteContact.phone}</span>
            </a>
            <p className="footer-address">
              <Icon name="pin" size={18} /><span>{footer.address}</span>
            </p>
          </div>
        </nav>
        <a className="footer-back-top" href="#top" aria-label={accessibility.backToTop}>
          <Icon name="arrow-up-right" size={22} />
        </a>
      </div>
      <nav className="footer-legal section-shell" aria-label={footer.documents}>
        <Link href={`/${locale}/terms`}>{footer.terms}<Icon name="arrow-up-right" size={14} /></Link>
        <Link href={`/${locale}/privacy`}>{footer.privacy}<Icon name="arrow-up-right" size={14} /></Link>
      </nav>
      <div className="footer-bottom section-shell">
        <span>{footer.copyright}</span>
        <p>{footer.demoNotice}</p>
        <span className="footer-made"><Icon name="pin" size={14} />{footer.country}</span>
      </div>
      <details className="photo-credits section-shell">
        <summary>{footer.photoCredits}<Icon name="chevron-down" size={14} /></summary>
        <p>{footer.photoCreditNote}</p>
        <ul>
          {imageCredits.map((photo) => (
            <li key={photo.id}>
              <a href={photo.source} target="_blank" rel="noreferrer">
                {dictionary.destinations[photo.id].title} — {photo.author}
              </a>
              <a href={photo.licenseUrl} target="_blank" rel="noreferrer">{photo.license}</a>
            </li>
          ))}
        </ul>
      </details>
    </footer>
  );
}
